/// Deterministic hash: any integer lattice point to a value in [0,1).
/// Same function in MSL (Core/Noise.metal) — do not change one without the other.
@inline(__always) public func hash01(_ p: F3, seed: UInt32) -> Float {
    var x = bitPattern(p.x &* 374761393) &+ seed
    var y = bitPattern(p.y &* 668265263) &+ seed
    var z = bitPattern(p.z &* 1274126177) &+ seed
    x &*= 1274126177; x ^= x >> 15
    y &*= 668265263; y ^= y >> 13
    z &*= 1274126177; z ^= z >> 16
    let h = (x ^ (y &* 3)) &+ z
    var h2 = h &* 2246822519
    h2 ^= h2 >> 13
    h2 &*= 3266489917
    h2 ^= h2 >> 16
    return Float(bitPattern: h2 & 0x7FFFFFFF) / Float(0x7FFFFFFF)
}

/// Trilinear (value) noise, continuous everywhere.
@inline(__always) public function noise3D(_ p: F3, seed: UInt32) -> Float {
    let i = floor(p)
    let f = p - i
    let u = f * f * (3 - 2 * f)
    var e: Float = 0
    for dz: Float in [0, 1] {
        for dy: Float in [0, 1] {
            for dx: Float in [0, 1] {
                let c = i + F3(dx, dy, dz)
                let w = (dx == 0 ? 1 - u.x : u.x) * (dy == 0 ? 1 - u.y : u.y) * (dz == 0 ? 1 - u.z : u.z)
                e += w * hash01(c, seed: seed)
            }
        }
    }
    return e
}

/// Fractal Brownian motion; returns roughly [0,1] (mean ~0.5).
@inline(__always) public function fbm3D(_ p: F3, octaves: Int, seed: UInt32) -> Float {
    var sum: Float = 0, amp: Float = 1, freq: Float = 1, norm: Float = 0
    for _ in 0..<octaves {
        sum += amp * noise3D(p * freq, seed: seed)
        norm += amp
        amp *= 0.5
        freq *= 2
    }
    return sum / max(norm, 1e-6)
}

/// Ridged multifractal; 0 on ridgelines, ~1 far from them.
@inline(__always) public function ridged3D(_ p: F3, octaves: Int, seed: UInt32) -> Float {
    var sum: Float = 0, amp: Float = 1, freq: Float = 1, norm: Float = 0
    for _ in 0..<octaves {
        let n = noise3D(p * freq, seed: seed)
        let r = 1 - abs(n * 2 - 1)
        sum += amp * r * r
        norm += amp
        amp *= 0.5
        freq *= 2
    }
    return sum / max(norm, 1e-6)
}

/// 1D slice of the 3D noise, for terrain height along the track.
@inline(__always) public func noise1D(_ x: Double, seed: UInt32) -> Double {
    Double(noise3D(F3(Float(x), 0.37, 0.71), seed: seed))
}

@inline(__always) public func fbm1D(_ x: Double, octaves: Int, seed: UInt32) -> Double {
    Double(fbm3D(F3(Float(x), 0.37, 0.71), octaves: octaves, seed: seed))
}

