// 1000 nits: the sun disc and its specular glints sit above white, the sky tops out at
// 280, fireflies and embers stay paper white, and everything else keeps its old values.
// The curve below must map 1.0 -> 1.0 and 280 -> 280 exactly, or the sky would shift.
float3 encode10(float3 linear, constant float &maxEncoding,
                constant float3 &sd, constant float &sdI) {
    if (maxEncoding > 2.0) {
        // 1000 nits: 1.0 -> 1.0, 280 -> 280, 1000 -> 1000
        if (all(linear <= 1.0)) {
            return pow(max(linear, 0.0), 1.0 / 2.2);
        }
        if (all(linear <= 280.0)) {
            return pow(linear / 280.0, 1.0 / 2.2) * 280.0 / 1000.0;
        }
        return min(linear / 1000.0, 1.0);
    }
    if (maxEncoding > 1.0) {
        // 540 nits: 1.0 -> 1.0, 280 -> 280
        if (all(linear <= 1.0)) {
            return pow(max(linear, 0.0), 1.0 / 2.2);
        }
        if (all(linear <= 280.0)) {
            return pow(linear / 280.0, 1.0 / 2.2) * 280.0 / 540.0;
        }
        return min(linear / 540.0, 1.0);
    }
    // SDR: Reinhard knee at 0.76, then the 2.2 gamma
    float3 x = min(linear, 100.0);
    x = select(x, (x * (1.0 + x / 0.76)) / (1.0 + x), any(x > 1.0));
    return pow(max(x, 0.0), 1.0 / 2.2);
}

// The 3D buffer is drawn smaller than the surface and shown with a 4-tap Catmull-Rom
// filter, so detail from the higher-resolution surface shows through the gaps.
kernel void upscale(device const float4* src      [[buffer(0)]],
                    device uchar4        * dst     [[buffer(1)]],
                    constant float       & maxEnc  [[buffer(2)]],
                    constant float4      & params  [[buffer(3)]],   // srcW srcH dstW dstH
                    uint2 gid [[thread_position_in_grid]]) {
    uint2 dstSize = uint2(params.z, params.w);
    if (any(gid >= dstSize)) return;
    float2 srcSize = params.xy;
    float2 texel = 1.0 / srcSize;
    float2 uv = (float2(gid) + 0.5) * srcSize / float2(dstSize);
    float2 tc = uv * srcSize - 0.5;
    float2 f = fract(max(tc, 0.0));
    int2 base = int2(max(tc, 0.0));
    device const float4* s0 = src + base.y * uint(srcSize.x);
    device const float4* s1 = min(s0 + uint(srcSize.y), src + uint(srcSize.x) * uint(srcSize.y) - 4);
    device const float4* s2 = min(s0 + uint(srcSize.x), src + uint(srcSize.y) * uint(srcSize.x) - 4);
    device const float4* s3 = min(s0 + uint(srcSize.x) * 2, src + uint(srcSize.y) * uint(srcSize.x) - 4);
    device const float4* s4 = min(s0 + uint(srcSize.x) * 3, src + uint(srcSize.y) * uint(srcSize.x) - 4);

