final class AppDelegate: NSObject, NSApplicationDelegate, NSWindowDelegate {
    var window: NSWindow!
    var view: MTKView!
    var ctl: GameController!
    var lastTime = CACurrentMediaTime()

    func applicationDidFinishLaunching(_ note: Notification) {
        guard let device = MTLCreateSystemDefaultDevice() else {
            fatalError("no Metal device")
        }
        do {
            ctl = try GameController(device: device, settings: Storage.load(Settings.self, "settings.json") ?? Settings(), audio: true)
        } catch {
            fatalError("init: \(error)")
        }
        ctl.onQuit = { [weak self] in
            self?.window.close()
            self?.window = nil
            NSApp.terminate(nil)
        }

        let screen = NSScreen.main!
        let frame = screen.frame
        window = NSWindow(contentRect: NSRect(origin: .zero, size: frame.size),
                          styleMask: [.borderless], backing: .deferred, defer: false)
        window.isOpaque = true
        window.hasShadow = false
        window.level = .mainMenu + 1
        window.collectionBehavior = [.stationary, .ignoresCycle, .fullScreenAuxiliary]
        window.isRestorable = false

        view = MTKView(frame: NSRect(origin: .zero, size: frame.size), device: device)
        view.colorPixelFormat = .bgra8Unorm_srgb
        view.clearColor = MTLClearColor(red: 0.05, green: 0.07, blue: 0.12, alpha: 1)
        view.framebufferOnly = false
        view.enableSetNeedsDisplay = false
        view.isPaused = false
        view.delegate = self
        window.contentView = view
        window.makeKeyAndOrderFront(nil)
        window.makeFirstResponder(view)
        NSApp.activate(ignoringOtherApps: true)
        view.acceptsFirstMouse = true
        view.nextKeyView = nil
        installKeyHandler()
        installMouse()
        window.orderFrontRegardless()
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ app: NSApplication) -> Bool { true }

    // MARK: input

    func installKeyHandler() {
        NSEvent.addLocalMonitorForEvents(matching: [.keyDown, .flagsChanged]) { [weak self] e in
            guard let self, let v = self.view, v.window?.isKeyWindow == true else { return e }
            if e.type == .keyDown, e.keyCode == 53 {   // esc: quit, never close the window
                self.ctl.onQuit()
                return nil
            }
            if e.type == .keyDown, e.modifierFlags.contains(.command), e.charactersIgnoringModifiers == "w" {
                self.ctl.onQuit()
                return nil
            }
            if e.type == .keyDown, e.isARepeat { return e }
            if let k = KeyMap.map(e) { self.ctl.input.keys.insert(k) }
            return nil
        }
    }

    func installMouse() {
        view.window?.ignoresMouseEvents = false
        view.nextResponder = view   // keep mouse inside
    }
}

extension AppDelegate: MTKViewDelegate {
    func mtkView(_ view: MTKView, drawableSizeWillChange size: CGSize) {}

    func draw(in view: MTKView) {
        let now = CACurrentMediaTime()
        var dt = now - lastTime
        lastTime = now
        dt = min(dt, 1.0 / 20)
        ctl.frame(dt: dt)
        guard let pass = view.currentRenderPassDescriptor,
              let drawable = view.currentDrawable,
              let cmdbuf = view.commandQueue?.makeCommandBuffer() else { return }
        do {
            try ctl.renderer.render(game: ctl.game, overlay: ctl.overlay, to: pass, commandBuffer: cmdbuf)
            cmdbuf.present(drawable)
            cmdbuf.commit()
        } catch {
            FileHandle.standardError.write("render: \(error)\n".data(using: .utf8)!)
        }
    }
}

