// Talking to the printer: port 9100 for raw jobs and PJL commands,
// and the embedded web server for settings the PJL set doesn't cover.

struct PrinterDevice: Identifiable, Codable, Equatable {
    var id: String { address }
    var address: String      // IP or hostname
    var name: String
    var source: Source

    enum Source: String, Codable, CaseIterable {
        case bonjour, saved, manual
    }
}

enum PrinterError: LocalizedError {
    case notFound(String)
    case connection(String)
    case io(String)
    case http(String)
    case rejected

    var errorDescription: String? {
        switch self {
        case .notFound(let s): return "Couldn't find a printer at \(s)."
        case .connection(let s): return "Couldn't connect: \(s)"
        case .io(let s): return "Communication problem: \(s)"
        case .http(status: let c, body: let b): return "The web server returned HTTP \(c). \(b.prefix(120))"
        case .rejected: return "The printer rejected the data."
        }
    }
}

extension PrinterError {
    init(_ e: Error) {
        switch e {
        case let e as URLError: self = .connection(e.localizedDescription)
        case let e as NWError: self = .connection(e.localizedDescription)
        default: self = .io(e.localizedDescription)
        }
    }
}

// MARK: - Raw port 9100

actor RawLink {
    private var connection: NWConnection?
    private let host: NWEndpoint.Host
    private let idleTimeout: NWParameters.IdleTimeout = .seconds(30)

    init(host: NWEndpoint.Host) { self.host = host }

    private func connect() throws -> NWConnection {
        if let c = connection, c.state == .ready { return c }
        connection?.cancel()
        let params = NWParameters.tcp
        if let idle = idleTimeout { params.defaultProtocolPath.idleTimeoutOptions = NWProtocolTCP.IdleTimeoutOptions(idleTimeout: idle) }
        let c = NWConnection(host: host, port: 9100, using: params)
        c.stateUpdateHandler = { [weak c] s in if case .failed = s { c?.cancel() } }
        connection = c
        c.start(queue: .global(qos: .userInitiated))
        return c
    }

    private func receive(_ c: NWConnection, _ count: Int) async throws -> Data {
        do {
            let (data, _) = try await c.receive(minimumIncompleteLength: count, maximumLength: count)
            guard let data, !data.isEmpty else { throw PrinterError.io("The printer closed the connection.") }
            return data
        } catch let e as PrinterError { throw e }
        catch let e as NWError where e.code == 2 { throw PrinterError.io("The printer closed the connection.") }
        catch { throw PrinterError(e) }
    }

    private func send(_ c: NWConnection, _ data: Data) async throws {
        do { try await c.send(content: data, completion: .content(timeout: 30_000)) }
        catch let e as NWError {
            if e.code == 2 { throw PrinterError.io("The printer closed the connection.") }
            throw PrinterError(e)
        }
    }

