def is_simple_power(x, n):
    """Your task is to write a function that returns true if a number x is a simple
    power of n and false in other cases.
    x is a simple power of n if n**int=x
    For example:
    is_simple_power(1, 4) => true
    is_simple_power(2, 2) => true
    is_simple_power(8, 2) => true
    is_simple_power(3, 2) => false
    is_simple_power(3, 1) => false
    is_simple_power(5, 3) => false
    """
    if n == 1:
        return x == 1
    if n == 0:
        return x == 0
    if n < 0:
        # Handle negative base: n^k must equal x
        # For negative n, we need to check if there exists an integer k such that n^k == x
        # Since n is negative, n^k alternates sign based on k parity
        # We need to check if x can be expressed as n^k for some integer k >= 0
        # But note: if n is negative and x is positive, k must be even
        # If x is negative, k must be odd
        # Let's handle this by checking powers
        if x == 1:
            return True  # n^0 = 1
        if x == 0:
            return False  # n^k != 0 for n != 0
        # Check if |x| is a power of |n| and sign matches
        abs_x = abs(x)
        abs_n = abs(n)
        if abs_n == 0:
            return False
        # Find if abs_x is a power of abs_n
        if abs_x == 0:
            return False
        # Check powers of abs_n
        power = 1
        k = 0
        while power < abs_x:
            power *= abs_n
            k += 1
        if power == abs_x:
            # Check if sign matches: n^k should equal x
            # If k is even, n^k is positive; if k is odd, n^k is negative
            if k % 2 == 0:
                return x > 0
            else:
                return x < 0
        return False
    # n > 0
    if x == 1:
        return True  # n^0 = 1
    if x == 0:
        return False  # n^k != 0 for n > 0
    if x < 0:
        return False  # n^k > 0 for n > 0
    # Check if x is a power of n
    power = 1
    while power < x:
        power *= n
    return power == x


